+        process_handle: pi.hProcess,
+        thread_handle: pi.hThread,
+        pid: pi.dwProcessId,
+        stdout_read,
+        stderr_read,
+        acl_snapshots,
+        net_snapshot,
+        job,
+        restored: false,
+    })
+}
