+/// A sandboxed child process spawned with a restricted token.
+pub struct SandboxedChild {
+    process_handle: HANDLE,
+    thread_handle: HANDLE,
+    pub pid: u32,
+    stdout_read: HANDLE,
+    stderr_read: HANDLE,
+    acl_snapshots: Vec<PathAclSnapshot>,
+    net_snapshot: NetPolicySnapshot,
