+        let exit_code = unsafe {
+            WaitForSingleObject(self.process_handle, INFINITE);
+            let mut code: u32 = 0;
+            GetExitCodeProcess(self.process_handle, &mut code)
+                .map_err(|e| format!("GetExitCodeProcess failed: {e}"))?;
+            code as i32
+        };
