+        let acl_err = restore_path_policy(snapshots).err();
+        let net_err = restore_net_policy(net).err();
+        if let Some(e) = net_err.or(acl_err) {
+            return Err(e);
+        }
+
+        Ok(exit_code)
+        // Drop closes ALL handles (child is dead, safe to close job too).
+    }
